import { CommandeGerantService } from './CommandeGerant'

export class CommandeScannerService {
  static async processScannedQRCode(qrText: string) {
    console.log('[CommandeScannerService] Scanned QR payload:', qrText)
    try {
      // The QR payload was generated by GenerateOrderQRCodeUseCase, it's JSON string
      const decoded = JSON.parse(qrText)
      const orderId = decoded?.orderId || decoded?.id || decoded?.id_commande
      if (!orderId) throw new Error('Invalid QR code payload: missing orderId')

      // Fetch order details for this restaurant / gerant
      const order = await CommandeGerantService.getOrder(orderId)
      if (!order) throw new Error('Commande non trouvée ou non liée au restaurant')

      // Mark the order as delivered directly
      const updated = await CommandeGerantService.updateOrderStatus(orderId, 'livree')

      // Normalize the order to the structure used in the view
      const normalize = (o: any) => {
        const customer = o?.client ? `${o.client?.prenom || ''} ${o.client?.nom || ''}`.trim() : 'Client'
        const items = (o.items || []).map((it: any) => ({ name: it.nom || it.name, qty: it.quantite || it.qty, price: it.prix || it.price }))
        const status = (o.statut || o.status || '').toLowerCase()
        return {
          id: o.id_commande || o.id || orderId,
          customer,
          items,
          total: o.montant_total || o.total || 0,
          address: o.livraison || '',
          status: status.includes('livr') ? 'livrée' : status.includes('cours') ? 'en cours' : 'aucun',
        }
      }

      // If updated successfully, adjust the order status locally
      const normalized = normalize(order)
      if (updated) normalized.status = 'livrée'

      return normalized
    } catch (e) {
      console.error('[CommandeScannerService] Error processing QR scan', e)
      return null
    }
  }
}
